-- name: CreateTeamScript :one
INSERT INTO scripts (team_id, name, description, body, default_args, env_names, run_as, timeout_seconds, created_by)
VALUES (sqlc.arg('team_id'), sqlc.arg('name'), sqlc.arg('description'), sqlc.arg('body'), sqlc.arg('default_args'),
        sqlc.arg('env_names'), sqlc.arg('run_as'), sqlc.arg('timeout_seconds'), sqlc.arg('created_by'))
RETURNING *;

-- name: UpdateTeamScript :one
UPDATE scripts SET name = sqlc.arg('name'), description = sqlc.arg('description'), body = sqlc.arg('body'),
    default_args = sqlc.arg('default_args'), env_names = sqlc.arg('env_names'), run_as = sqlc.arg('run_as'),
    timeout_seconds = sqlc.arg('timeout_seconds'), updated_at = now()
WHERE team_id = sqlc.arg('team_id') AND id = sqlc.arg('id')
RETURNING *;

